  // Compress image to thumbnail for library storage — prevents localStorage overflow
  const compressForLibrary = (dataUrl) => new Promise((res) => {
    const img = new window.Image();
    img.onload = () => {
      const canvas = document.createElement("canvas");
      const MAX = 300;
      const ratio = Math.min(MAX/img.width, MAX/img.height);
      canvas.width = Math.round(img.width * ratio);
      canvas.height = Math.round(img.height * ratio);
      canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
      res(canvas.toDataURL("image/jpeg", 0.7));
    };
    img.onerror = () => res(dataUrl);
    img.src = dataUrl;
  });

  const resizeImageTo1080 = (dataUrl) => new Promise((res) => {
    const img = new window.Image();
    img.onload = () => {
      const MAX = 1080;
      if (img.width <= MAX && img.height <= MAX) { res(dataUrl); return; }
      const ratio = Math.min(MAX/img.width, MAX/img.height);
      const canvas = document.createElement("canvas");
      canvas.width = Math.round(img.width * ratio);
      canvas.height = Math.round(img.height * ratio);
      canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
      res(canvas.toDataURL("image/png"));
    };
    img.onerror = () => res(dataUrl);
    img.src = dataUrl.startsWith("_c_data:") ? dataUrl.replace(/^_c_data:/, "data:") : dataUrl;
  });
  const isIosSafari = () => { try { const ua=navigator.userAgent; return /iP(ad|hone|od)/.test(ua)&&/WebKit/.test(ua)&&!/CriOS|FxiOS|EdgiOS/.test(ua); } catch { return false; } };

